<script setup lang="ts">
import {ref} from 'vue'
import AppModal from './AppModal.vue'
import {request} from '@/services/quality'
import {officineService,type SupportAssignment} from '@/services/officine'
const props=defineProps<{requestId:number}>();const emit=defineEmits<{saved:[]}>()
const open=ref(false),busy=ref(false),error=ref(''),version=ref(0),assignment=ref(0),role=ref('member'),confirmed=ref(false)
const choices=ref<SupportAssignment[]>([]),team=ref<{id:number;name:string;role:string;status:string}[]>([])
async function prepare(){open.value=true;busy.value=true;error.value='';confirmed.value=false;try{const d=await request<{version:number;officine_id:number;team:typeof team.value}>(`/support/intake/${props.requestId}/team`);version.value=d.version;team.value=d.team;choices.value=(await officineService.proposals(d.officine_id)).filter(a=>['pending','approved'].includes(a.status)&&a.permissions.includes('accompagnement.read'));assignment.value=choices.value[0]?.id||0}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function save(){busy.value=true;error.value='';try{await request(`/support/intake/${props.requestId}/team`,'POST',{version:version.value,assignment_id:assignment.value,role:role.value,confirmed:confirmed.value});open.value=false;emit('saved')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><button class="button secondary" @click="prepare">Préparer l’équipe de mission</button><AppModal v-model="open" title="Proposer une participation à la mission" :busy="busy" size="wide"><form id="mission-team-proposal" class="form-body correction-form" @submit.prevent="save"><p v-if="error" class="alert error" role="alert">{{error}}</p><p>Aucun accès n’est accordé par cette proposition. L’officine doit approuver la portée M1 puis la participation à cette mission.</p><p v-for="m in team" :key="m.id">{{m.name}} · {{m.role==='lead'?'Responsable':'Intervenant'}} · {{m.status}}</p><label>Affectation M1<select v-model="assignment" required><option :value="0" disabled>Sélectionner une affectation</option><option v-for="a in choices" :key="a.id" :value="a.id">{{a.name}} · {{a.scope}} · {{a.status}}</option></select></label><p v-if="!choices.length">Aucune affectation avec permission Accompagnement. Proposez d’abord sa portée et sa période dans la coordination des accès.</p><RouterLink to="/beg/accompagnateurs" class="text-link">Coordination des accès M1</RouterLink><label>Rôle dans la mission<select v-model="role"><option value="member">Intervenant</option><option value="lead">Responsable de mission</option></select></label><p>Un responsable nécessite les permissions de consultation et de contribution Accompagnement.</p><label class="checkbox-label"><input v-model="confirmed" type="checkbox" required/>Je confirme la proposition, sans approbation au nom de l’officine.</label></form><template #footer><button class="button secondary" :disabled="busy" @click="open=false">Annuler</button><button class="button primary" :disabled="busy||!assignment" type="submit" form="mission-team-proposal">Proposer la participation</button></template></AppModal></template>
